inline const CQR *GetCQR(const void *buf) {
  return ::flatbuffers::GetRoot<CQR>(buf);
}

inline const CQR *GetSizePrefixedCQR(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<CQR>(buf);
}

inline const char *CQRIdentifier() {
  return "$CQR";
}

inline bool CQRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CQRIdentifier());
}

inline bool SizePrefixedCQRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CQRIdentifier(), true);
}

template <bool B = false>
inline bool VerifyCQRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<CQR>(CQRIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedCQRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<CQR>(CQRIdentifier());
}

inline void FinishCQRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CQR> root) {
  fbb.Finish(root, CQRIdentifier());
}

inline void FinishSizePrefixedCQRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CQR> root) {
  fbb.FinishSizePrefixed(root, CQRIdentifier());
}

inline std::unique_ptr<CQRT> UnPackCQR(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<CQRT>(GetCQR(buf)->UnPack(res));
}

inline std::unique_ptr<CQRT> UnPackSizePrefixedCQR(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<CQRT>(GetSizePrefixedCQR(buf)->UnPack(res));
}

